/// <summary>
/// MPJ_34596_TransferOrderFinalisation The <c>MetTransferOrderAutoShipService</c> class exposes services for auto shipment creation.
/// </summary>
public class MetTransferOrderAutoShipService
{
    #OCCRetryCount

    private boolean                             errorsFound;
    container                                   transferOrderShipCon;


}

Method.Source:
    private void autoTransferShipmentCreation(
        InventTransferTable _transferTable)
    {
        setPrefix(strFmt("@SYP4860552", _transferTable.TransferId));
        
        try
        { 
            int recordCount;
            MetTransferShipmentTable    metTransferShipmentTable;
            MetTransferShipmentLine     metTransferShipmentLine;
            NumberSeq                   numberSeqShipmentId,numberSeqLoadId;
            MetShipmentId               metShipmentId;
            MetLoadId                   metLoadID;
            InventTransferTable         inventTransferTable;
            METInventTransferTableExt   metInventTransferTableExt;
            InventTransferId            inventTransferId;
            RecordInsertList            metTransferShipmentTableInsertList,metTransferShipmentLineInsertList;

            numberSeqShipmentId = NumberSeq::newGetNum(InventParameters::numRefMetShippingID());
            metShipmentId = numberSeqShipmentId.num();

            numberSeqLoadId = NumberSeq::newGetNum(InventParameters::numRefMetLoadID());
            metLoadID       = numberSeqLoadId.num();

            metTransferShipmentTableInsertList = new RecordInsertList(tableNum(MetTransferShipmentTable));
            metTransferShipmentLineInsertList = new RecordInsertList(tableNum(MetTransferShipmentLine));
        
            for(recordCount = 1; recordCount <= conLen(transferOrderShipCon); recordCount++)
            {
                inventTransferId    = conPeek(transferOrderShipCon,recordCount);
              
                if(recordCount == 1)
                {
                    inventTransferTable = InventTransferTable::find(inventTransferId);
                    select  firstonly metInventTransferTableExt where
                    metInventTransferTableExt.InventTransferTable   == inventTransferTable.RecId;

                    metTransferShipmentTable.ShipmentId      = metShipmentId;
                    metTransferShipmentTable.LoadId          = metLoadID;
                    metTransferShipmentTable.ShipmentStatus  = MetShipmentStatus::Loaded;
                    metTransferShipmentTable.FromWarehouse      = inventTransferTable.InventLocationIdFrom;
                    metTransferShipmentTable.ToWarehouse        = inventTransferTable.InventLocationIdTo;
                    metTransferShipmentTable.ShipDate           = inventTransferTable.ShipDate;
                    metTransferShipmentTable.Route              = metInventTransferTableExt.Route;
                    metTransferShipmentTable.RouteStopNum       = metInventTransferTableExt.RouteStopNum;
                  
                    metTransferShipmentTableInsertList.add(metTransferShipmentTable);
                }

                metTransferShipmentline.ShipmentId       = metShipmentId;
                metTransferShipmentline.TransferId          = inventTransferId;
                metTransferShipmentline.LineNum            += 1;
                metTransferShipmentline.HazardousMaterial   =  this.checkIfHazardousMaterial(inventTransferId);
                metTransferShipmentLineInsertList.add(metTransferShipmentline);

                //dataContract.parmMetShipmentId(metShipmentId);
            }
            metTransferShipmentTableInsertList.insertDatabase();
            metTransferShipmentLineInsertList.insertDatabase();
      
        }
        catch (Exception::Error)
        {
            errorsFound = true;
        }
        catch (Exception::Deadlock)
        {
            retry;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() != 0)
            {
                throw Exception::UpdateConflict;
            }
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            retry;
        }
       

    }

    /// <summary>
    /// Auto ship TO
    /// </summary>
    /// <param name="_contract">
    /// Parameters
    /// </param>
    /// <exception cref="Exception::Error">
    /// Throws an error if the specified contract is not valid.
    /// </exception>
    /// <exception cref="Exception::Error">
    /// Throws an error if called in transaction scope.
    /// </exception>
    public void autoShipTransferOrders(MetTransferOrderAutoShipContract _contract)
    {
        errorsFound = false;
        InventTransferTable inventTransferTable;

        if (!_contract.validate())
        {
            throw error("@SYS78886");
        }


        QueryRun queryRunTransfers = new QueryRun(this.transferOrdersShipQuery(_contract));
       
        while (queryRunTransfers.next())
        {
            inventTransferTable      = queryRunTransfers.get(tableNum(InventTransferTable));
            transferOrderShipCon     = conIns(transferOrderShipCon, conLen(transferOrderShipCon) + 1, inventTransferTable.TransferId);
        }

        if(conLen(transferOrderShipCon))
        {
            this.autoTransferShipmentCreation(inventTransferTable);
        }
        else
        {
            warning("@MET:NoTransferOrderToProcess");
        }

    }

    /// <summary>
    /// Check Hazardous material
    /// </summary>
    /// <param name = "_transferid">TransferId</param>
    /// <returns>NoYes</returns>
    public NoYes checkIfHazardousMaterial(InventTransferId _transferid)
    {
        InventTransferLine          inventTransferLine;
        InventTable                 InventTable;

        select firstonly inventTransferLine
                    where inventTransferLine.TransferId == _transferid
          exists join InventTable
                    where InventTable.ItemId == inventTransferLine.ItemId
                     && InventTable.HMIMIndicator == NoYes::Yes;

        if(inventTransferLine)
        {
            return NoYes::Yes;
        }
        else
        {
            return NoYes::No;

        }


    }

    /// <summary>
    /// get the query 
    /// </summary>
    /// <param name = "_contract">atuoshipContract</param>
    /// <returns>Query</returns>
    private Query transferOrdersShipQuery(MetTransferOrderAutoShipContract _contract)
    {
        Query query = _contract.parmQuery();
        QueryBuildDataSource  dsTransferLines = query.dataSourceTable(tableNum(InventTransferTable));
        dsTransferLines.addRange(fieldNum(InventTransferTable, TransferStatus)).value(enum2Str(InventTransferStatus::Created));

        dsTransferLines = query.dataSourceTable(tableNum(InventTransferTable)).addDataSource(tableNum(InventLocation));
        dsTransferLines.relations(true);
        dsTransferLines.joinMode(JoinMode::ExistsJoin);

        dsTransferLines = query.dataSourceTable(tableNum(InventLocation)).addDataSource(tableNum(METInventLocation));
        dsTransferLines.relations(true);
        dsTransferLines.joinMode(JoinMode::ExistsJoin);
        dsTransferLines.addRange(fieldNum(METInventLocation, AutoShipment)).value(enum2Str(NoYes::Yes));

        dsTransferLines = query.dataSourceTable(tableNum(InventTransferTable)).addDataSource(tableNum(MetTransferShipmentLine));
        dsTransferLines.relations(true);
        dsTransferLines.joinMode(JoinMode::NoExistsJoin);
       

        return query;
    }
